from pathlib import Path
import json
root=Path('dist'); root.mkdir(exist_ok=True)
css='''*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#f6f6ef;color:#173d32;font-family:Arial,sans-serif}a{color:inherit;text-decoration:none}button,input,select{font:inherit}a:focus-visible,button:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid #a35428;outline-offset:5px}header{padding:24px 5%;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #d4dcd2;gap:20px}.brand{font-size:28px;font-weight:800;letter-spacing:-1px}.brand small{display:block;font-size:10px;letter-spacing:3px;margin-top:5px}nav{display:flex;align-items:center;gap:25px;font-size:14px}.button,button{display:inline-block;border:0;border-radius:5px;padding:16px 23px;background:#173d32;color:white;cursor:pointer;font-weight:600}.light{background:#daf49a;color:#173d32}.hero{display:grid;grid-template-columns:1.1fr 1fr;min-height:660px;padding:60px 5% 40px;gap:35px}.eyebrow{text-transform:uppercase;font-size:11px;letter-spacing:2px;font-weight:bold}.hero h1{font-size:clamp(50px,5.7vw,85px);line-height:1.02;letter-spacing:-4px;font-weight:500;margin:32px 0}.hero h1 em{font-style:normal;color:#668266}.intro{font-size:18px;line-height:1.65;max-width:480px;color:#53675e}.actions{display:flex;gap:20px;align-items:center;margin-top:30px}.product{position:relative;background:#e0e7dc;border-radius:160px 160px 12px 12px;display:flex;align-items:center;justify-content:center;overflow:hidden;min-height:510px}.product img{width:72%;height:420px;object-fit:contain;mix-blend-mode:multiply;filter:drop-shadow(15px 25px 18px #6f807933)}.product .tag{position:absolute;bottom:25px;left:28px;background:#fff;padding:16px 20px;border-radius:5px;font-size:12px}.zero{position:absolute;right:25px;top:25px;font-size:70px;font-weight:300}.zero small{display:block;font-size:11px;letter-spacing:1px}.strip{background:#173d32;color:#f3f6e9;display:flex;justify-content:space-around;gap:20px;padding:28px 5%;font-size:13px}section{padding:85px 5%}.sectionhead{display:flex;justify-content:space-between;gap:35px;align-items:end;margin-bottom:40px}h2{font-size:clamp(32px,3.4vw,50px);font-weight:500;line-height:1.1;letter-spacing:-1.5px;margin:15px 0}h3{font-weight:500;font-size:23px}.sectionhead p{max-width:380px;line-height:1.7;color:#53675e}.steps{display:grid;grid-template-columns:repeat(3,1fr);gap:40px}.step{border-top:1px solid #b8c7b9;padding-top:25px}.step span{font-size:13px;color:#65816c}.step p{line-height:1.7;color:#53675e}.calc{background:#e8ede2}.calcgrid{display:grid;grid-template-columns:1.2fr 1fr;gap:50px}.inputs{display:grid;grid-template-columns:1fr 1fr;gap:20px}label{font-size:12px;display:block;line-height:1.5}input,select{width:100%;padding:13px;margin-top:7px;border:1px solid #bac9bc;background:#fff;border-radius:4px;color:#173d32}.results{background:#173d32;color:#fff;padding:35px;border-radius:8px}.results strong{display:block;font-size:45px;font-weight:500;margin:12px 0 20px}.results .smallnumber{font-size:29px}.results hr{border:0;border-top:1px solid #5f776c;margin:25px 0}.note{font-size:12px;line-height:1.7;color:#53675e;margin-top:20px}.results .note{color:#d5dfd8}.faq{display:grid;grid-template-columns:1fr 1.2fr;gap:70px}details{border-top:1px solid #bdcabc;padding:23px 0}summary{cursor:pointer;line-height:1.6}details p{line-height:1.7;color:#53675e}.quote{background:#d9e5cd;display:grid;grid-template-columns:1fr 1fr;gap:60px}.quote form{display:grid;gap:16px}.quote p{line-height:1.7}footer{padding:35px 5%;display:flex;justify-content:space-between;font-size:12px}.textlink{text-decoration:underline;text-underline-offset:5px}@media(max-width:760px){header{flex-wrap:wrap}nav{gap:16px;font-size:12px;flex-wrap:wrap}.hero,.calcgrid,.faq,.quote{grid-template-columns:1fr}.hero{padding-top:35px}.hero h1{letter-spacing:-2px}.product{min-height:420px}.product img{height:350px}.strip{flex-wrap:wrap;justify-content:flex-start}.steps{grid-template-columns:1fr;gap:20px}.sectionhead{display:block}section{padding:60px 6%}.inputs{gap:12px}.actions{flex-wrap:wrap}footer{gap:20px;flex-wrap:wrap}}'''
(root/'style.css').write_text(css)
data={
'en':dict(other='fr',switch='FR',title='URIMAT Canada | Waterless urinals for commercial buildings',nav=['How it works','Savings','Plan your project'],eyebrow='A fresh approach to commercial washrooms',h1='Save fresh<br>drinking water.<br><em>Every single day.</em>',intro='Make flushing water a thing of the past. Explore URIMAT waterless urinals for your building, with practical guidance from Swiss Eco Media.',cta='Calculate your savings',secondary='Explore the technology ↗',tag='URIMAT ECO / WATERLESS URINAL',zero='litres per flush',strip=['Zero flushing water','Gravity-driven drainage','A clear maintenance routine'],how='Simple by design.',howtext='A waterless urinal still connects to drainage. What changes is how urine leaves the bowl and how odour is controlled.',steps=[('Let gravity do the work','Urine flows into the drainage system without a flush cycle or flushing water supply.'),('Keep odour in check','The MB Active odour trap is a core part of the system. Correct installation and care matter.'),('Keep care consistent','Clean routinely and replace consumables as required. Waterless does not mean maintenance-free.')],calc='What could your building save?',calctext='Start with an estimate. Replace every example value with your own building data.',labels=['Number of urinals','Uses per urinal / day','Operating days / year','Existing litres / flush','Water + wastewater CAD / m³','Existing maintenance CAD / year, site','Waterless care CAD / year, site','Installed conversion cost CAD, site'],results=['Avoided flush water / year','Gross utility savings / year','Net operating savings / year','Simple payback'],years='years',none='No positive payback',note='Illustrative assumptions, not a quote or municipal rate. Includes the costs entered above. Excludes taxes, financing, fixed utility charges, cleaning water and future cost changes.',faqhead='Good questions.<br>Clear answers.',faqs=[('Does it really use no flushing water?','Yes. Waterless urinals use no water for flushing. Cleaning still requires an appropriate routine and products.'),('Will it work in my existing washroom?','A retrofit may be possible. Drainage, mounting, existing plumbing and local requirements need a site-specific assessment.'),('What about odour and cleaning?','The odour trap, correct installation and consistent cleaning all play a role. Your team needs instructions and a consumables replacement routine.'),('Can I get a site-specific price?','Yes. Call Swiss Eco Media to discuss your location, quantities and project scope. Calculator values are examples, not prices.')],quote='A better washroom<br>starts with your building.',qtext='Prepare a short project brief, then discuss it with our team.',qnote='This planner downloads a text file to your device. It does not send or store your inquiry.',city='City / province',facility='Facility type',qty='Urinal quantity',options=['Office building','School or university','Arena or recreation','Restaurant or hospitality','Other facility'],download='Download project brief',call='Talk to our team',status='Your brief is ready. Nothing has been submitted.',footer='A Swiss Eco Media website',downloadname='urimat-project-brief.txt'),
'fr':dict(other='en',switch='EN',title='URIMAT Canada | Urinoirs sans eau pour bâtiments commerciaux',nav=['Fonctionnement','Économies','Votre projet'],eyebrow='Une nouvelle approche des sanitaires commerciaux',h1='Préservez notre<br>eau potable.<br><em>Chaque jour.</em>',intro='Découvrez les urinoirs sans eau URIMAT pour votre bâtiment, avec les conseils pratiques de Swiss Eco Media.',cta='Calculer vos économies',secondary='Découvrir la technologie ↗',tag='URIMAT ECO / URINOIR SANS EAU',zero='litre par chasse',strip=['Aucune eau de chasse','Évacuation par gravité','Un entretien bien défini'],how='La simplicité, par conception.',howtext='Un urinoir sans eau reste raccordé au réseau d’évacuation. La différence se trouve dans l’évacuation de l’urine et le contrôle des odeurs.',steps=[('Laisser agir la gravité','L’urine s’écoule vers le réseau d’évacuation sans cycle de chasse ni alimentation en eau de chasse.'),('Maîtriser les odeurs','Le dispositif anti-odeurs MB Active est au cœur du système. Une installation correcte et un entretien adapté sont essentiels.'),('Entretenir régulièrement','Nettoyez régulièrement et remplacez les consommables selon les besoins. Sans eau ne signifie pas sans entretien.')],calc='Que pourrait économiser votre bâtiment ?',calctext='Commencez par une estimation. Remplacez chaque valeur illustrative par les données de votre bâtiment.',labels=['Nombre d’urinoirs','Utilisations par urinoir / jour','Jours d’activité / an','Litres par chasse actuelle','Eau + eaux usées CAD / m³','Entretien actuel CAD / an, bâtiment','Entretien sans eau CAD / an, bâtiment','Coût de conversion installé CAD'],results=['Eau de chasse évitée / an','Économies brutes de services / an','Économies nettes d’exploitation / an','Récupération simple'],years='ans',none='Aucune récupération positive',note='Hypothèses illustratives, ni devis ni tarif municipal. Inclut les coûts saisis. Exclut les taxes, le financement, les frais fixes, l’eau de nettoyage et les variations futures des coûts.',faqhead='Vos questions.<br>Des réponses claires.',faqs=[('Aucune eau de chasse, vraiment ?','Oui. Les urinoirs sans eau n’utilisent aucune eau pour la chasse. Le nettoyage nécessite toujours une routine et des produits adaptés.'),('Est-ce adapté à mes sanitaires existants ?','Une conversion peut être possible. L’évacuation, la fixation, la plomberie et les exigences locales nécessitent une évaluation du site.'),('Qu’en est-il des odeurs et du nettoyage ?','Le dispositif anti-odeurs, une installation correcte et un nettoyage régulier sont essentiels. Votre équipe a besoin de consignes et d’un calendrier de remplacement des consommables.'),('Puis-je obtenir un prix pour mon projet ?','Oui. Appelez Swiss Eco Media pour discuter du lieu, des quantités et de la portée du projet. Les valeurs du calculateur sont des exemples, pas des prix.')],quote='De meilleurs sanitaires.<br>Un projet adapté à vous.',qtext='Préparez un bref descriptif de votre projet, puis discutez-en avec notre équipe.',qnote='Cet outil télécharge un fichier texte sur votre appareil. Il ne transmet ni ne conserve votre demande.',city='Ville / province',facility='Type de bâtiment',qty='Nombre d’urinoirs',options=['Immeuble de bureaux','École ou université','Aréna ou loisirs','Restaurant ou hôtellerie','Autre bâtiment'],download='Télécharger le descriptif',call='Parler à notre équipe',status='Votre descriptif est prêt. Rien n’a été envoyé.',footer='Un site de Swiss Eco Media',downloadname='projet-urimat.txt')}
for lang,d in data.items():
 p=root/lang;p.mkdir(exist_ok=True)
 inputs=''.join(f'<label>{label}<input type="number" id="v{i}" min="{1 if i<3 else 0}" '+('max="366" ' if i==2 else '')+f'step="{1 if i<3 else "any"}" value="{[10,100,260,1.9,5,600,1800,20000][i]}" required></label>' for i,label in enumerate(d['labels']))
 steps=''.join(f'<article class="step"><span>0{i+1}</span><h3>{a}</h3><p>{b}</p></article>' for i,(a,b) in enumerate(d['steps']))
 faqs=''.join(f'<details><summary>{a}</summary><p>{b}</p></details>' for a,b in d['faqs'])
 html=f'''<!doctype html><html lang="{lang}-CA"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>{d['title']}</title><meta name="description" content="{d['intro']}"><link rel="stylesheet" href="/style.css"><link rel="icon" href="/favicon.svg"></head><body><header><a class="brand" href="/{lang}/">URIMAT<small>CANADA / SWISS ECO MEDIA</small></a><nav><a href="#how">{d['nav'][0]}</a><a href="#savings">{d['nav'][1]}</a><a href="#project">{d['nav'][2]} ↗</a><a class="textlink" href="/{d['other']}/" lang="{d['other']}">{d['switch']}</a></nav></header><main><div class="hero"><div><p class="eyebrow">{d['eyebrow']}</p><h1>{d['h1']}</h1><p class="intro">{d['intro']}</p><div class="actions"><a class="button" href="#savings">{d['cta']} ↗</a><a class="textlink" href="#how">{d['secondary']}</a></div></div><div class="product"><div class="zero">0<small>{d['zero']}</small></div><img src="/assets/urimat-eco.png" alt="URIMAT Eco" width="430" height="500"><div class="tag">{d['tag']}</div></div></div><div class="strip">{''.join('<span>✓ &nbsp;'+x+'</span>' for x in d['strip'])}</div><section id="how"><div class="sectionhead"><div><p class="eyebrow">01 / {d['nav'][0]}</p><h2>{d['how']}</h2></div><p>{d['howtext']}</p></div><div class="steps">{steps}</div></section><section class="calc" id="savings"><div class="sectionhead"><div><p class="eyebrow">02 / {d['nav'][1]}</p><h2>{d['calc']}</h2></div><p>{d['calctext']}</p></div><div class="calcgrid"><form id="calculator" class="inputs">{inputs}</form><div class="results" aria-live="polite"><span>{d['results'][0]}</span><strong id="water"></strong><hr><span>{d['results'][1]}</span><strong class="smallnumber" id="gross"></strong><span>{d['results'][2]}</span><strong class="smallnumber" id="net"></strong><span>{d['results'][3]}</span><strong class="smallnumber" id="payback"></strong></div></div><p class="note">{d['note']}</p></section><section class="faq"><div><p class="eyebrow">03 / FAQ</p><h2>{d['faqhead']}</h2></div><div>{faqs}</div></section><section class="quote" id="project"><div><p class="eyebrow">04 / {d['nav'][2]}</p><h2>{d['quote']}</h2><p>{d['qtext']}</p><p>{d['call']}<br><a class="textlink" href="tel:+18882709899">1 888 270 9899</a></p></div><form id="brief"><label>{d['city']}<input id="city" maxlength="100" required autocomplete="address-level2"></label><label>{d['facility']}<select id="facility">{''.join('<option>'+x+'</option>' for x in d['options'])}</select></label><label>{d['qty']}<input id="quantity" type="number" min="1" max="100000" step="1" value="10" required></label><p class="note">{d['qnote']}</p><button type="submit">{d['download']} ↓</button><p id="status" role="status"></p></form></section></main><footer><span>© 2026 Swiss Eco Media · {d['footer']}</span><a href="https://swissecomedia.ca">Swiss Eco Media ↗</a></footer><script>window.COPY={json.dumps(dict(lang=lang,years=d['years'],none=d['none'],status=d['status'],filename=d['downloadname']),ensure_ascii=False)};</script><script src="/app.js"></script></body></html>'''
 (p/'index.html').write_text(html)
(root/'index.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="robots" content="noindex"><meta http-equiv="refresh" content="0;url=/en/"><title>URIMAT Canada</title><a href="/en/">English</a> <a href="/fr/">Français</a></html>')
(root/'favicon.svg').write_text('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" rx="12" fill="#173d32"/><text x="32" y="46" text-anchor="middle" font-family="Arial" font-weight="bold" font-size="42" fill="#daf49a">U</text></svg>')
